export const EMOTION_PROFILES = {
  stressed:   { depth: 1, skill: 1, elo: 1320 },
  frustrated: { depth: 2, skill: 3, elo: 1320 },
  calm:       { depth: 4, skill: 6, elo: 1600 },
  neutral:    { depth: 6, skill: 10, elo: 2000 },
  focused:    { depth: 8, skill: 15, elo: 2600 },
  confident:  { depth: 10, skill: 20, elo: 3190 },
};

export function clampElo(elo: number) {
  return Math.max(1320, Math.min(3190, elo));
}
